"""Embed artifacts/model.json verbatim in the Worker bundle as a JSON string literal."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
source = ROOT / "artifacts" / "model.json"
target = ROOT / "backend" / "src" / "infra" / "model_payload.py"
text = source.read_text(encoding="utf-8").strip()
json.loads(text)  # fail early on invalid JSON
if not text.isascii() or "\\" in text or "'''" in text:
    raise ValueError("model.json cannot be embedded verbatim in a raw string literal")
target.write_text(
    "# Generated by scripts/package_model.py from artifacts/model.json. Do not edit.\n"
    "import json\n\n"
    f"MODEL = json.loads(r'''{text}''')\n",
    encoding="utf-8",
)
print(f"Packaged {source} into {target} ({target.stat().st_size} bytes)")
